/** The solar position algorithm. */
enum class Calculator(val value: Int) {
    /** The NOAA algorithm, KosherJava's default. Good to about a minute. */
    Noaa(0),
    /** Jean Meeus's higher-accuracy VSOP87 algorithm. */
    Meeus(1),
    /** The NREL Solar Position Algorithm, solved on the topocentric zenith. */
    Spa(2);

    companion object {
        /** The variant whose ABI value is [value]. */
        fun fromValue(value: Int): Calculator = entries.firstOrNull { it.value == value }
            ?: throw NativeBugException(-3, "unknown Calculator value $value")
    }
}

/** Why a time in `ZmanTime` could not be calculated. */
enum class ZmanFailure(val value: Int) {
    /** The sun stays above the angle the time needs all day. */
    AllDay(0),
    /** The sun stays below the angle the time needs all day. */
    AllNight(1),
    /** The time does not apply on this date. */
    NotApplicable(2),
    /**
     * The time needs a time zone and none was given. Only the four Kiddush Levana times need
     * one.
     */
    TimeZoneRequired(3),
    /** The time zone callback failed. */
    TimeZoneCallbackFailed(4),
    /** An internal calculation error. */
    Unexpected(5);

    companion object {
        /** The variant whose ABI value is [value]. */
        fun fromValue(value: Int): ZmanFailure = entries.firstOrNull { it.value == value }
            ?: throw NativeBugException(-3, "unknown ZmanFailure value $value")
    }
}

/**
 * A place on earth: where to calculate *zmanim* for. Heights are in meters above sea level;
 * leave them 0 for sea level.
 *
 * The time zone is not part of the location. You pass a `TimeZoneOffset` to `Zmanim` and
 * `MyZmanim` when you create them.
 */
data class Location(
    /** Latitude in degrees, north positive. */
    val latitude: Double,
    /** Longitude in degrees, east positive. */
    val longitude: Double,
    /** The observer's height. Elevation makes sunrise earlier and sunset later. */
    val elevation: Double,
    /** The height of the eastern horizon, over which the sun rises. */
    val eastern_horizon_elevation: Double,
    /** The height of the western horizon, behind which the sun sets. */
    val western_horizon_elevation: Double,
)

internal fun packLocation(_w: BufferWriter, _v: Location) {
    _w.writeF64(_v.latitude)
    _w.writeF64(_v.longitude)
    _w.writeF64(_v.elevation)
    _w.writeF64(_v.eastern_horizon_elevation)
    _w.writeF64(_v.western_horizon_elevation)
}

internal fun unpackLocation(_r: BufferReader): Location = Location(
    _r.readF64(),
    _r.readF64(),
    _r.readF64(),
    _r.readF64(),
    _r.readF64(),
)

/** How `Zmanim` calculates. `default_config` matches KosherJava's defaults. */
data class Config(
    /**
     * How long before sea-level sunset candle lighting is, in minutes, from 0 to 1440.
     * Default 18.
     */
    val candle_lighting_minutes: Int,
    /** Whether proportional zmanim divide the day at astronomical *chatzos*. Default false. */
    val use_astronomical_chatzos_for_other_zmanim: Boolean,
    /**
     * Whether elevation adjusts every zman built on sunrise and sunset, not only sunrise
     * and sunset themselves. Default false.
     */
    val use_elevation: Boolean,
    /**
     * How long after sunset Tzais Ateret Torah is, in minutes, at most 1440 either way.
     * Default 40.
     */
    val ateret_torah_sunset_minutes: Int,
    /**
     * Whether *chatzos* is the sun's transit rather than the midpoint of sunrise and
     * sunset. Default true.
     */
    val use_astronomical_chatzos: Boolean,
    /** The solar position algorithm. Default NOAA. */
    val calculator: Calculator,
    /** For Meeus and SPA: whether to apply the delta-T (TT - UT) correction. Default true. */
    val apply_delta_t: Boolean,
)

internal fun packConfig(_w: BufferWriter, _v: Config) {
    _w.writeI32(_v.candle_lighting_minutes)
    _w.writeBool(_v.use_astronomical_chatzos_for_other_zmanim)
    _w.writeBool(_v.use_elevation)
    _w.writeI32(_v.ateret_torah_sunset_minutes)
    _w.writeBool(_v.use_astronomical_chatzos)
    _w.writeI32(_v.calculator.value)
    _w.writeBool(_v.apply_delta_t)
}

internal fun unpackConfig(_r: BufferReader): Config = Config(
    _r.readI32(),
    _r.readBool(),
    _r.readBool(),
    _r.readI32(),
    _r.readBool(),
    Calculator.fromValue(_r.readI32()),
    _r.readBool(),
)

/** One zman's time, or why it has none. */
data class ZmanTime(
    /** The zman. */
    val zman: Zman,
    /** The time in Unix milliseconds, when it could be calculated. */
    val time: Long?,
    /** Why it could not, when it could not. */
    val failure: ZmanFailure?,
)

internal fun packZmanTime(_w: BufferWriter, _v: ZmanTime) {
    _w.writeI32(_v.zman.value)
    packOptionalOfI64(_w, _v.time)
    packOptionalOfZmanFailure(_w, _v.failure)
}

internal fun unpackZmanTime(_r: BufferReader): ZmanTime = ZmanTime(
    Zman.fromValue(_r.readI32()),
    unpackOptionalOfI64(_r),
    unpackOptionalOfZmanFailure(_r),
)

/**
 * The time zone. You supply it as a callback with two methods. One gives the offset from UTC
 * at an instant. The other gives the instant of a local date and time. Java's `ZoneId`, .NET's
 * `TimeZoneInfo`, Python's `zoneinfo` and JavaScript's `Temporal` can answer both.
 *
 * The time zone is optional. With a time zone every time works. You can also leave it out.
 * These do not work without a time zone:
 *
 * - The four Kiddush Levana times return `ZmanimError::TimeZoneRequired`.
 * - `Zmanim` and `MyZmanim` cannot be created for a location more than 150 degrees from
 *   Greenwich. Creating them returns `ZmanimError::TimeZoneRequired`.
 *
 * The callback is called synchronously, once for each sunrise, sunset or other event that a
 * time is built from.
 */
interface TimeZoneOffset {
    /**
     * The offset from UTC, in seconds east, in effect at `unix_seconds`.
     *
     * # Errors
     *
     * Fail when the offset is unknown. The calculation then reports
     * `ZmanimError::TimeZoneCallbackFailed`.
     */
    fun offsetSeconds(unixSeconds: Long): Int

    /**
     * The Unix time, in seconds, at which the clocks in this time zone show the local date
     * and time given.
     *
     * Resolve it the way Java's `ZonedDateTime.of` does. When the clocks skip over the time,
     * return the instant one gap length later. When the clocks show the time twice, return
     * the earlier instant. JavaScript's `Temporal` calls this the `compatible`
     * disambiguation, and it is Temporal's default.
     *
     * # Errors
     *
     * Fail when the instant is unknown. The calculation then reports
     * `ZmanimError::TimeZoneCallbackFailed`.
     */
    fun localToUnixSeconds(year: Int, month: Int, day: Int, hour: Int, minute: Int, second: Int): Long
}

/** The *zmanim* for one place on one day. */
class Zmanim private constructor(address: Long) : AutoCloseable {
    internal val handle: NativeHandle = NativeCleaner.register(this, NativeHandle(address, JniBridge::times_Zmanim_destroy))

    /** A new strong reference to this object, as written into a value buffer. */
    internal fun cloneHandle(): Long = handle.borrow { JniBridge.times_Zmanim_clone(it) }

    /**
     * The time of `zman`, in Unix milliseconds.
     *
     * # Errors
     *
     * `ZmanimError::AllDay` or `ZmanimError::AllNight` where the sun never reaches
     * the angle the time needs; `ZmanimError::NotApplicable` for a time that only exists
     * on some days; `ZmanimError::TimeZoneRequired` for the Kiddush Levana times without
     * a time zone; `ZmanimError::TimeZoneCallbackFailed` when the callback failed.
     */
    fun get(zman: Zman): Long = handle.borrow { _self ->
        JniBridge.times_Zmanim_get(_self, zman.value)
    }

    /** Every zman, with its time or why it has none. */
    fun all(): List<ZmanTime> = handle.borrow { _self ->
        decodeBuffer(JniBridge.times_Zmanim_all(_self)) { _r -> unpackListOfZmanTime(_r) }
    }

    /**
     * When the sun is `degrees` below the geometric horizon before sunrise, in Unix
     * milliseconds.
     *
     * # Errors
     *
     * `ZmanimError::InvalidDegrees` when `degrees` is not a number from -90 to 90; otherwise
     * the same as `get`.
     */
    fun sunriseOffsetByDegrees(degrees: Double): Long = handle.borrow { _self ->
        JniBridge.times_Zmanim_sunrise_offset_by_degrees(_self, degrees)
    }

    /**
     * When the sun is `degrees` below the geometric horizon after sunset, in Unix
     * milliseconds.
     *
     * # Errors
     *
     * `ZmanimError::InvalidDegrees` when `degrees` is not a number from -90 to 90; otherwise
     * the same as `get`.
     */
    fun sunsetOffsetByDegrees(degrees: Double): Long = handle.borrow { _self ->
        JniBridge.times_Zmanim_sunset_offset_by_degrees(_self, degrees)
    }

    /** The location. */
    fun location(): Location = handle.borrow { _self ->
        decodeBuffer(JniBridge.times_Zmanim_location(_self)) { _r -> unpackLocation(_r) }
    }

    /** The date. */
    fun date(): GregorianDate = handle.borrow { _self ->
        decodeBuffer(JniBridge.times_Zmanim_date(_self)) { _r -> unpackGregorianDate(_r) }
    }

    /** The configuration, as given to `new`. */
    fun config(): Config = handle.borrow { _self ->
        decodeBuffer(JniBridge.times_Zmanim_config(_self)) { _r -> unpackConfig(_r) }
    }

    /** Releases this wrapper's native reference; safe to call more than once. */
    override fun close() = handle.close()

    companion object {
        /** Adopts one strong reference (a return value or a buffer token). */
        internal fun fromHandle(address: Long): Zmanim = Zmanim(address)

        /** [fromHandle], with address 0 meaning no object. */
        internal fun fromHandleOrNull(address: Long): Zmanim? = if (address == 0L) null else Zmanim(address)

        /**
         * The *zmanim* at `location` on `date` in `time_zone`, calculated with `config`.
         *
         * The time zone is optional. With a time zone every time works. Without one the four
         * Kiddush Levana times return `ZmanimError::TimeZoneRequired`. A location more than 150
         * degrees from Greenwich needs a time zone. Without one this returns
         * `ZmanimError::TimeZoneRequired`.
         *
         * # Errors
         *
         * - `ZmanimError::InvalidGregorianDate` when the date does not exist.
         * - `ZmanimError::InvalidMinutes` when the candle-lighting offset is negative, or it or the
         *   Ateret Torah offset is more than a day.
         * - The errors of `validate_location`. This includes `ZmanimError::TimeZoneRequired` when
         *   there is no time zone and the location is more than 150 degrees from Greenwich.
         */
        operator fun invoke(location: Location, date: GregorianDate, config: Config, timeZone: TimeZoneOffset?): Zmanim = Zmanim.fromHandle(JniBridge.times_Zmanim_new(encodeBuffer { _w -> packLocation(_w, location) }, encodeBuffer { _w -> packGregorianDate(_w, date) }, encodeBuffer { _w -> packConfig(_w, config) }, timeZone))
    }
}

